def verify_fork_aggregate_chains(items, prune_policy, site_policy,
                                 keyring, moment):
    """Verify a batch of fork aggregate chains and spot successor forks.

    Each item holds exactly a unique non-empty ``id``, its ``root``
    aggregate packet, its ordered ``successors`` packets and its
    per-stage ``policies`` history; ``prune_policy`` is the invariant
    original pruning policy and ``site_policy`` the invariant
    fork-proof site policy shared by every chain, and ``keyring`` and
    ``moment`` keep their single-chain meaning.  The whole batch
    structure -- every key set, element type, policy count and the
    shared materials -- is validated before any chain is verified, so
    only batch-level faults raise (container, element or field type
    faults :class:`TypeError`, a :class:`bool` never posing as an int;
    an empty list, an empty or duplicate id, a wrong policy count or an
    illegal moment :class:`ValueError`).

    Each chain is then verified independently, in strict input order,
    through the exact :func:`verify_fork_aggregate_chain` rules: one
    chain's failure never stops a later chain or changes an earlier
    report.  A root fault reports ``invalid-root``, a successor or
    chain-binding fault ``invalid-chain`` and a credential or signature
    fault ``unauthenticated``, each with a null ``result``; a passing
    chain reports ``verified``.

    The verified chains are grouped by their ``rootDigest`` and only
    successor trajectories under the same aggregate root are compared:
    the same predecessor digest pointing at two distinct successor
    digests is a fork (a mere prefix extension is not).  Every verified
    chain crossing a forking edge is reclassified ``conflicted`` with
    its verified result kept and its ``error`` fixed to
    ``"forked-fork-aggregate-chain"``; invalid and unauthenticated
    chains are never reclassified.

    Returns a fresh dict with the fixed keys ``forks``, ``items`` and
    ``version`` (the integer 1).  ``forks`` is sorted by ``rootDigest``
    then ``predecessorDigest``; each entry carries exactly
    ``rootDigest``, ``predecessorDigest``, ``successors`` (the forking
    successor digests, ascending) and ``ids`` (the ascending ids of the
    chains crossing the edge).  Each item report preserves the input
    order and carries, in this key order, ``error``, ``id``, ``result``
    and ``status``.  No file is read or written and no input is
    modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(site_policy)
    _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    reports: list[dict] = []
    results: list[dict | None] = []
    for item in validated_items:
        report = _verify_fac_chain_item(
            item, prune_policy, site_policy, keyring, verify_moment
        )
        reports.append(report)
        results.append(report[VERDICT_ITEM_RESULT])

    # Fork detection within one root group: one predecessor digest
    # pointing at two distinct successor digests, ignoring chains that
    # did not verify.
    groups: dict[str, dict[str, set[str]]] = {}
    for item, result in zip(validated_items, results):
        if result is None:
            continue
        nodes = _pac_chain_edge_nodes(item)
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    fork_edges: dict[tuple[str, str], list[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                fork_edges[(root_digest, upstream)] = sorted(digests)
    edge_ids: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in fork_edges
    }
    if fork_edges:
        for item, report, result in zip(validated_items, reports, results):
            if result is None:
                continue
            nodes = _pac_chain_edge_nodes(item)
            crosses_fork = False
            for upstream in nodes[:-1]:
                edge = (nodes[0], upstream)
                if edge in fork_edges:
                    edge_ids[edge].add(item[ID])
                    crosses_fork = True
            if crosses_fork:
                report[STATUS] = PAC_CHAINS_CONFLICTED
                report[CHECKPOINT_ITEM_ERROR] = _FAC_CHAIN_ITEM_ERROR

    forks = [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: fork_edges[(root_digest, predecessor)],
            _FORK_IDS: sorted(edge_ids[(root_digest, predecessor)]),
        }
        for root_digest, predecessor in sorted(fork_edges)
    ]
    return {
        CHAINS_FORKS: forks,
        ITEMS: reports,
        VERSION: FORK_AGGREGATE_CHAINS_VERSION,
    }


# -- Stable head anchors for verified, accepted, unforked chains ---------------

def _parse_fac_anchor(raw: object) -> tuple[dict, str]:
    """Validate anchor bytes structurally into ``(payload, signature)``."""
    if not isinstance(raw, bytes):
        raise TypeError("anchor must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _fac_chain_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _fac_chain_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_fac_keys
        )
    except json.JSONDecodeError as exc:
        raise _fac_chain_invalid("is not valid JSON") from exc
    if not isinstance(data, dict):
        raise TypeError("anchor must be a JSON object")
    if set(data.keys()) != _FAC_ANCHOR_TOP_KEYS:
        raise _fac_chain_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("anchor signature must be a str")
    if not _prune_is_digest(signature):
        raise _fac_chain_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("anchor payload must be an object")
    if set(payload.keys()) != _FAC_ANCHOR_PAYLOAD_KEYS:
        raise _fac_chain_invalid(
            "payload must contain exactly the keys 'rootDigest', "
            "'headDigest', 'height', 'policyDigest', 'policyVersion', "
            "'moment', 'issuer', 'keyVersion' and 'version'"
        )
    for key in (FAC_ROOT_DIGEST, FAC_HEAD_DIGEST, FAC_POLICY_DIGEST):
        value = payload[key]
        if not isinstance(value, str):
            raise TypeError(f"payload {key} must be a str")
        if not _prune_is_digest(value):
            raise _fac_chain_invalid(
                f"payload {key} must be 64 lowercase hex characters"
            )
    height = payload[FAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError("payload height must be an int")
    if height < 0:
        raise _fac_chain_invalid("payload height must be non-negative")
    policy_version = payload[FAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError("payload policyVersion must be an int")
    if policy_version <= 0:
        raise _fac_chain_invalid("payload policyVersion must be positive")
    anchor_moment = payload[CP_MOMENT]
    if isinstance(anchor_moment, bool) or not isinstance(anchor_moment, int):
        raise TypeError("payload moment must be an int")
    if anchor_moment < 0:
        raise _fac_chain_invalid("payload moment must be non-negative")
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _fac_chain_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _fac_chain_invalid("payload keyVersion must be positive")
    anchor_version = payload[VERSION]
    if isinstance(anchor_version, bool) or not isinstance(
        anchor_version, int
    ):
        raise TypeError("payload version must be an int")
    if anchor_version != FORK_AGGREGATE_CHAIN_VERSION:
        raise _fac_chain_invalid("payload version must be the integer 1")
    if _prune_compact(data) != raw:
        raise _fac_chain_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature


def seal_fork_aggregate_head(
    items, target, prune_policy, site_policy, keyring, moment, issuer, version
):
    """Seal a stable anchor over one target head within the batch.

    The batch is first run through the exact
    :func:`verify_fork_aggregate_chains` rules.  An anchor is sealed
    only for the ``target`` chain when it is ``verified`` -- never
    conflicted by a fork in this batch, invalid or unauthenticated --
    and its head is ``accepted``; otherwise sealing raises
    :class:`ValueError`.  Other chains' failures never stop the
    target's anchor, though their forks still reclassify it when they
    share an edge.  The anchor binds that chain's root digest, head
    digest and height together with the head decision policy digest,
    the head policy version and the sealing moment, and is signed with
    HMAC-SHA256 under the exact ``issuer``/``version`` key usable at
    ``moment``.

    Returns canonical compact UTF-8 JSON with exactly ``payload`` and
    ``signature``.  A parameter or public field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an
    empty value, an unknown or duplicate target id, an illegal version
    or a wrong policy count raises :class:`ValueError`; a chain fault
    raises the underlying
    :class:`InvalidAggregateForkDecisionAggregateError` or
    :class:`InvalidForkAggregateChainError`; a signing credential fault
    raises :class:`AuthenticationError`.  No file is read or written
    and no input is modified.
    """
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    seal_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_fork_aggregate_chains(
        items, prune_policy, site_policy, keyring, seal_moment
    )
    entry_report = report[ITEMS][target_index]
    if entry_report[STATUS] != PAC_CHAINS_VERIFIED:
        raise ValueError(
            "an anchor seals only a verified target with no fork"
        )
    result = entry_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise ValueError("an anchor seals only an accepted head")
    target_item = validated_items[target_index]
    head_packet = (
        target_item[PAC_BATCH_SUCCESSORS][-1]
        if target_item[PAC_BATCH_SUCCESSORS] else target_item[PAC_BATCH_ROOT]
    )
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    if result[FAC_HEAD_DIGEST] != hashlib.sha256(head_packet).hexdigest():
        raise ValueError("the sealed head digest does not match its packet")
    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, seal_moment
    )
    payload = {
        FAC_ROOT_DIGEST: result[FAC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: result[FAC_HEAD_DIGEST],
        FAC_HEIGHT: result[FAC_HEIGHT],
        FAC_POLICY_DIGEST: _pac_policy_digest(head_policy),
        FAC_POLICY_VERSION: result[FAC_POLICY_VERSION],
        CP_MOMENT: seal_moment,
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        VERSION: FORK_AGGREGATE_CHAIN_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def verify_fork_aggregate_head(
    anchor, items, target, prune_policy, site_policy, keyring, moment
):
    """Re-verify a sealed fork aggregate anchor entirely offline.

    The anchor is checked structurally and its HMAC verified against
    the current keyring key bound to its exact issuer and version,
    usable at the verification ``moment``.  The original batch (with
    ``target`` naming the anchored chain) is then re-run through
    :func:`verify_fork_aggregate_chains`; the target must again verify
    with no fork and an accepted head, and its root digest, head
    digest, height and policy version must equal the anchor bindings
    while the bound policy digest must equal the digest of the target's
    head policy.

    Returns a fresh mapping with fixed keys ``rootDigest``,
    ``headDigest``, ``height``, ``policyDigest``, ``policyVersion`` and
    ``anchorDigest`` (the SHA-256 of the anchor bytes).  A non-bytes or
    wrong-type argument raises :class:`TypeError`; an empty value, a
    duplicate or unknown target id, an illegal version or a wrong policy
    count raises :class:`ValueError`; a bad anchor, successor or chain
    binding raises :class:`InvalidForkAggregateChainError`; a malformed
    root raises :class:`InvalidAggregateForkDecisionAggregateError`; a
    signature or credential fault raises :class:`AuthenticationError`.
    No file is read or written and no input is modified.
    """
    if not isinstance(anchor, bytes):
        raise TypeError("anchor must be bytes")
    payload, signature = _parse_fac_anchor(anchor)
    validated_items = _validated_fac_chain_batch(items)
    if not isinstance(target, str):
        raise TypeError("target must be a str")
    if target == "":
        raise ValueError("target must be non-empty")
    target_index = None
    for position, item in enumerate(validated_items):
        if item[ID] == target:
            target_index = position
            break
    if target_index is None:
        raise ValueError(f"unknown target id {target!r}")
    _validated_adjudication_policy(prune_policy)
    _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    verify_moment = _fe_moment(moment, "moment")

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        raise AuthenticationError(
            "fork aggregate anchor signature does not match"
        )

    report = verify_fork_aggregate_chains(
        items, prune_policy, site_policy, keyring, verify_moment
    )
    entry_report = report[ITEMS][target_index]
    if entry_report[STATUS] != PAC_CHAINS_VERIFIED:
        raise _fac_chain_invalid(
            "the anchored target no longer verifies without a fork"
        )
    result = entry_report[VERDICT_ITEM_RESULT]
    if result[STATUS] != PA_STATUS_ACCEPTED:
        raise _fac_chain_invalid("the anchored head is no longer accepted")
    target_item = validated_items[target_index]
    head_policy = _validated_pac_site_policy(
        target_item[PAC_BATCH_POLICIES][-1]
    )
    head_policy_digest = _pac_policy_digest(head_policy)
    if result[FAC_ROOT_DIGEST] != payload[FAC_ROOT_DIGEST]:
        raise _fac_chain_invalid("root digest does not match the anchor")
    if result[FAC_HEAD_DIGEST] != payload[FAC_HEAD_DIGEST]:
        raise _fac_chain_invalid("head digest does not match the anchor")
    if result[FAC_HEIGHT] != payload[FAC_HEIGHT]:
        raise _fac_chain_invalid("height does not match the anchor")
    if result[FAC_POLICY_VERSION] != payload[FAC_POLICY_VERSION]:
        raise _fac_chain_invalid(
            "policy version does not match the anchor"
        )
    if head_policy_digest != payload[FAC_POLICY_DIGEST]:
        raise _fac_chain_invalid("policy digest does not match the anchor")
    return {
        FAC_ROOT_DIGEST: payload[FAC_ROOT_DIGEST],
        FAC_HEAD_DIGEST: payload[FAC_HEAD_DIGEST],
        FAC_HEIGHT: payload[FAC_HEIGHT],
        FAC_POLICY_DIGEST: head_policy_digest,
        FAC_POLICY_VERSION: payload[FAC_POLICY_VERSION],
        FAC_ANCHOR_DIGEST: hashlib.sha256(anchor).hexdigest(),
    }

class InvalidAggregateForkProofError(ValueError):
    """A prune aggregate fork proof breaks its binding contract."""


def _pac_fork_proof_invalid(message: str) -> InvalidAggregateForkProofError:
    return InvalidAggregateForkProofError(
        f"invalid prune aggregate fork proof: {message}"
    )


def _reject_duplicate_pac_fork_proof_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate proof keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _pac_fork_proof_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _pac_chain_materials(validated_items: list[dict]) -> list[dict]:
    """Digest summary of every input chain, strictly in input order."""
    return [
        {
            ID: item[ID],
            PAC_BATCH_ROOT: hashlib.sha256(item[PAC_BATCH_ROOT]).hexdigest(),
            PAC_BATCH_SUCCESSORS: [
                hashlib.sha256(successor).hexdigest()
                for successor in item[PAC_BATCH_SUCCESSORS]
            ],
            PAC_BATCH_POLICIES: [
                _pac_policy_digest(validated_policy)
                for validated_policy in _pac_validated_policy_sequence(
                    item[PAC_BATCH_POLICIES]
                )
            ],
        }
        for item in validated_items
    ]


def _validated_pac_fork_chains(chains: object) -> list[dict]:
    """Validate the bound chain material summary into fresh ordered dicts.

    Each entry must carry exactly ``id`` (a non-empty str, unique across
    the summary), ``root`` (the chain root's digest), ``successors``
    (the ordered successor digests, possibly empty) and ``policies``
    (the per-stage policy digests, exactly one more than the
    successors).  A field of the wrong type raises :class:`TypeError`;
    every key-set, value-format or count fault raises
    :class:`InvalidAggregateForkProofError`.
    """
    if not isinstance(chains, list):
        raise TypeError("payload chains must be a list")
    if not chains:
        raise _pac_fork_proof_invalid("payload chains must be non-empty")
    validated: list[dict] = []
    seen_ids: set[str] = set()
    for position, chain in enumerate(chains):
        where = f"chain {position}"
        if not isinstance(chain, dict):
            raise TypeError(f"{where} must be an object")
        if set(chain.keys()) != _PAC_FORK_CHAIN_KEYS:
            raise _pac_fork_proof_invalid(
                f"{where} must contain exactly the keys 'id', 'policies', "
                "'root' and 'successors'"
            )
        chain_id = chain[ID]
        if not isinstance(chain_id, str):
            raise TypeError(f"{where} id must be a str")
        if chain_id == "":
            raise _pac_fork_proof_invalid(
                f"{where} id must be a non-empty str"
            )
        if chain_id in seen_ids:
            raise _pac_fork_proof_invalid(f"{where} repeats an id")
        seen_ids.add(chain_id)
        root = chain[PAC_BATCH_ROOT]
        if not isinstance(root, str):
            raise TypeError(f"{where} root must be a str")
        if not _prune_is_digest(root):
            raise _pac_fork_proof_invalid(
                f"{where} root must be 64 lowercase hex characters"
            )
        successors = chain[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        for hop_index, successor in enumerate(successors):
            if not isinstance(successor, str):
                raise TypeError(f"{where} successor {hop_index} must be a str")
            if not _prune_is_digest(successor):
                raise _pac_fork_proof_invalid(
                    f"{where} successor {hop_index} must be 64 lowercase hex "
                    "characters"
                )
        policies = chain[PAC_BATCH_POLICIES]
        if not isinstance(policies, list):
            raise TypeError(f"{where} policies must be a list")
        if not policies:
            raise _pac_fork_proof_invalid(
                f"{where} policies must be non-empty"
            )
        for policy_index, policy_digest in enumerate(policies):
            if not isinstance(policy_digest, str):
                raise TypeError(
                    f"{where} policy {policy_index} must be a str"
                )
            if not _prune_is_digest(policy_digest):
                raise _pac_fork_proof_invalid(
                    f"{where} policy {policy_index} must be 64 lowercase hex "
                    "characters"
                )
        if len(policies) != len(successors) + 1:
            raise _pac_fork_proof_invalid(
                f"{where} policies must provide one entry per chain stage "
                "(one more than the number of successors)"
            )
        validated.append({
            ID: chain_id,
            PAC_BATCH_ROOT: root,
            PAC_BATCH_SUCCESSORS: list(successors),
            PAC_BATCH_POLICIES: list(policies),
        })
    return validated


def _validated_pac_fork_chain_result(
    result: object, chain: dict, where: str
) -> None:
    """Validate one verified chain summary against its chain material.

    The summary must follow the exact :func:`verify_prune_aggregate_chain`
    result shape and every digest and the height must match the bound
    chain material.  A field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    key-set, value-format or binding fault raises
    :class:`InvalidAggregateForkProofError`.
    """
    if set(result.keys()) != _PAC_CHAIN_RESULT_KEYS:
        raise _pac_fork_proof_invalid(
            f"{where} result must contain exactly the keys 'commonDigest', "
            "'headDigest', 'height', 'policyVersion', 'rootDigest' and "
            "'status'"
        )
    root_digest = result[PAC_ROOT_DIGEST]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} result rootDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise _pac_fork_proof_invalid(
            f"{where} result rootDigest must be 64 lowercase hex characters"
        )
    if root_digest != chain[PAC_BATCH_ROOT]:
        raise _pac_fork_proof_invalid(
            f"{where} result rootDigest does not match the chain material"
        )
    head_digest = result[PAC_HEAD_DIGEST]
    if not isinstance(head_digest, str):
        raise TypeError(f"{where} result headDigest must be a str")
    if not _prune_is_digest(head_digest):
        raise _pac_fork_proof_invalid(
            f"{where} result headDigest must be 64 lowercase hex characters"
        )
    successors = chain[PAC_BATCH_SUCCESSORS]
    expected_head = successors[-1] if successors else chain[PAC_BATCH_ROOT]
    if head_digest != expected_head:
        raise _pac_fork_proof_invalid(
            f"{where} result headDigest does not match the chain material"
        )
    height = result[PAC_HEIGHT]
    if isinstance(height, bool) or not isinstance(height, int):
        raise TypeError(f"{where} result height must be an int")
    if height != len(successors):
        raise _pac_fork_proof_invalid(
            f"{where} result height does not match the chain material"
        )
    policy_version = result[PAC_POLICY_VERSION]
    if isinstance(policy_version, bool) or not isinstance(policy_version, int):
        raise TypeError(f"{where} result policyVersion must be an int")
    if policy_version <= 0:
        raise _pac_fork_proof_invalid(
            f"{where} result policyVersion must be positive"
        )
    status = result[STATUS]
    if not isinstance(status, str):
        raise TypeError(f"{where} result status must be a str")
    if status not in _PAC_CHAIN_RESULT_STATUSES:
        raise _pac_fork_proof_invalid(
            f"{where} result status is not a known stage status"
        )
    common_digest = result[PAC_COMMON_DIGEST]
    if common_digest is not None:
        if not isinstance(common_digest, str):
            raise TypeError(f"{where} result commonDigest must be a str")
        if not _prune_is_digest(common_digest):
            raise _pac_fork_proof_invalid(
                f"{where} result commonDigest must be 64 lowercase hex "
                "characters"
            )


def _validated_pac_fork_report(report: object, chains: list[dict]) -> None:
    """Validate the complete chain-batch report bound into a fork proof.

    The report must follow the exact
    :func:`verify_prune_aggregate_chains` shape -- ``forks``, ``items``
    and ``version`` (the integer 1) -- with at least one fork.  Every
    binding to the chain material summary is checked: the item count
    and per-position ids, each verified result's digests and height,
    and each fork's exact forking successors and crossing chains
    recomputed from the bound materials.  A field of the wrong type
    raises :class:`TypeError` (a :class:`bool` never poses as an int);
    every key-set, value, ordering, reference or binding fault raises
    :class:`InvalidAggregateForkProofError`.
    """
    if not isinstance(report, dict):
        raise TypeError("payload report must be an object")
    if set(report.keys()) != _PAC_FORK_REPORT_KEYS:
        raise _pac_fork_proof_invalid(
            "bound report must contain exactly the keys 'forks', 'items' "
            "and 'version'"
        )
    version = report[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("bound report version must be an int")
    if version != PRUNE_AGGREGATE_CHAINS_VERSION:
        raise _pac_fork_proof_invalid(
            "bound report version must be the integer 1"
        )

    items = report[ITEMS]
    if not isinstance(items, list):
        raise TypeError("bound report items must be a list")
    if not items:
        raise _pac_fork_proof_invalid("bound report items must be non-empty")
    if len(items) != len(chains):
        raise _pac_fork_proof_invalid(
            "bound report item count does not match the chain materials"
        )

    seen_ids: set[str] = set()
    for position, item_report in enumerate(items):
        where = f"bound report item {position}"
        if not isinstance(item_report, dict):
            raise TypeError(f"{where} must be an object")
        if set(item_report.keys()) != _PAC_FORK_ITEM_REPORT_KEYS:
            raise _pac_fork_proof_invalid(
                f"{where} must contain exactly the keys 'error', 'id', "
                "'result' and 'status'"
            )
        item_id = item_report[ID]
        if not isinstance(item_id, str):
            raise TypeError(f"{where} id must be a str")
        if item_id == "":
            raise _pac_fork_proof_invalid(
                f"{where} id must be a non-empty str"
            )
        if item_id != chains[position][ID]:
            raise _pac_fork_proof_invalid(
                f"{where} id does not match the chain material at its position"
            )
        if item_id in seen_ids:
            raise _pac_fork_proof_invalid(f"{where} repeats an id")
        seen_ids.add(item_id)
        status = item_report[STATUS]
        if not isinstance(status, str):
            raise TypeError(f"{where} status must be a str")
        if status not in _PAC_FORK_REPORT_STATUSES:
            raise _pac_fork_proof_invalid(
                f"{where} status is not a known status"
            )
        error = item_report[CHECKPOINT_ITEM_ERROR]
        result = item_report[VERDICT_ITEM_RESULT]
        if status == PAC_CHAINS_VERIFIED:
            if error is not None:
                raise _pac_fork_proof_invalid(
                    f"{where} error must be null when verified"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when verified"
                )
        elif status == PAC_CHAINS_CONFLICTED:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str when conflicted")
            if error != _PAC_CHAIN_ITEM_ERROR:
                raise _pac_fork_proof_invalid(
                    f"{where} error must be 'forked-aggregate-chain' when "
                    "conflicted"
                )
            if not isinstance(result, dict):
                raise TypeError(
                    f"{where} result must be an object when conflicted"
                )
        else:
            if not isinstance(error, str):
                raise TypeError(f"{where} error must be a str for a failure")
            if error == "":
                raise _pac_fork_proof_invalid(
                    f"{where} error must be a non-empty str for a failure"
                )
            if result is not None:
                raise _pac_fork_proof_invalid(
                    f"{where} result must be null for a failure"
                )
        if isinstance(result, dict):
            _validated_pac_fork_chain_result(result, chains[position], where)

    forks = report[CHAINS_FORKS]
    if not isinstance(forks, list):
        raise TypeError("bound report forks must be a list")
    if not forks:
        raise _pac_fork_proof_invalid(
            "a fork proof must report at least one fork"
        )

    # Recompute every edge from the bound materials over the items that
    # verified, then demand the bound fork entries match exactly -- the
    # same grouping and fork rule verify_prune_aggregate_chains uses.
    groups: dict[str, dict[str, set[str]]] = {}
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        edges = groups.setdefault(nodes[0], {})
        for upstream, downstream in zip(nodes, nodes[1:]):
            edges.setdefault(upstream, set()).add(downstream)
    expected_edges: dict[tuple[str, str], set[str]] = {}
    for root_digest, edges in groups.items():
        for upstream, digests in edges.items():
            if len(digests) > 1:
                expected_edges[(root_digest, upstream)] = digests
    crossing: dict[tuple[str, str], set[str]] = {
        edge: set() for edge in expected_edges
    }
    for chain, item_report in zip(chains, items):
        if not isinstance(item_report[VERDICT_ITEM_RESULT], dict):
            continue
        nodes = [chain[PAC_BATCH_ROOT]] + chain[PAC_BATCH_SUCCESSORS]
        for upstream in nodes[:-1]:
            edge = (nodes[0], upstream)
            if edge in expected_edges:
                crossing[edge].add(chain[ID])

    seen_edges: set[tuple[str, str]] = set()
    previous_edge: tuple[str, str] | None = None
    for position, fork in enumerate(forks):
        where = f"bound report fork {position}"
        if not isinstance(fork, dict):
            raise TypeError(f"{where} must be an object")
        if set(fork.keys()) != _PAC_CHAIN_FORK_KEYS:
            raise _pac_fork_proof_invalid(
                f"{where} must contain exactly the keys 'ids', "
                "'predecessorDigest', 'rootDigest' and 'successors'"
            )
        root_digest = fork[PAC_ROOT_DIGEST]
        predecessor = fork[PAC_PREDECESSOR_DIGEST]
        if not isinstance(root_digest, str):
            raise TypeError(f"{where} rootDigest must be a str")
        if not isinstance(predecessor, str):
            raise TypeError(f"{where} predecessorDigest must be a str")
        if not _prune_is_digest(root_digest):
            raise _pac_fork_proof_invalid(
                f"{where} rootDigest must be 64 lowercase hex characters"
            )
        if not _prune_is_digest(predecessor):
            raise _pac_fork_proof_invalid(
                f"{where} predecessorDigest must be 64 lowercase hex "
                "characters"
            )
        edge = (root_digest, predecessor)
        if edge in seen_edges:
            raise _pac_fork_proof_invalid(f"{where} repeats a fork edge")
        seen_edges.add(edge)
        if previous_edge is not None and edge < previous_edge:
            raise _pac_fork_proof_invalid(
                f"{where} forks must be sorted by rootDigest then "
                "predecessorDigest"
            )
        previous_edge = edge
        if edge not in expected_edges:
            raise _pac_fork_proof_invalid(
                f"{where} is not a fork in the bound chain materials"
            )
        successors = fork[PAC_BATCH_SUCCESSORS]
        if not isinstance(successors, list):
            raise TypeError(f"{where} successors must be a list")
        if any(not isinstance(successor, str) for successor in successors):
            raise TypeError(f"{where} successors must be strs")
        if any(not _prune_is_digest(successor) for successor in successors):
            raise _pac_fork_proof_invalid(
                f"{where} successors must be 64 lowercase hex characters"
            )
        if successors != sorted(successors) or len(set(successors)) != len(
            successors
        ):
            raise _pac_fork_proof_invalid(
                f"{where} successors must be unique and sorted ascending"
            )
        if set(successors) != expected_edges[edge]:
            raise _pac_fork_proof_invalid(
                f"{where} successors do not match the forking edge"
            )
        ids = fork[_FORK_IDS]
        if not isinstance(ids, list):
            raise TypeError(f"{where} ids must be a list")
        if any(not isinstance(fork_id, str) for fork_id in ids):
            raise TypeError(f"{where} ids must be strs")
        if any(fork_id == "" for fork_id in ids):
            raise _pac_fork_proof_invalid(f"{where} ids must be non-empty")
        if ids != sorted(ids) or len(set(ids)) != len(ids):
            raise _pac_fork_proof_invalid(
                f"{where} ids must be unique and sorted ascending"
            )
        if set(ids) != crossing[edge]:
            raise _pac_fork_proof_invalid(
                f"{where} ids do not match the chains crossing the edge"
            )

    if seen_edges != set(expected_edges):
        raise _pac_fork_proof_invalid(
            "the bound forks do not match the forking edges in the materials"
        )
    conflicted = {
        item_report[ID]
        for item_report in items
        if item_report[STATUS] == PAC_CHAINS_CONFLICTED
    }
    all_fork_ids: set[str] = set()
    for edge_crossing in crossing.values():
        all_fork_ids |= edge_crossing
    if conflicted != all_fork_ids:
        raise _pac_fork_proof_invalid(
            "the fork id sets must equal the conflicted report items"
        )


def _parse_pac_fork_proof(raw: object) -> tuple[dict, str, list[dict]]:
    """Validate fork proof bytes into ``(payload, signature, chains)``.

    A non-bytes argument or a public field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest, count, ordering, reference or
    report-binding fault raises
    :class:`InvalidAggregateForkProofError`.  The policy, moment,
    credential and signature bindings are checked by
    :func:`verify_prune_aggregate_fork_proof`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("proof must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pac_fork_proof_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pac_fork_proof_keys
        )
    except json.JSONDecodeError as exc:
        raise _pac_fork_proof_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("proof must be a JSON object")
    if set(data.keys()) != _PAC_FORK_PROOF_TOP_KEYS:
        raise _pac_fork_proof_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("proof signature must be a str")
    if not _prune_is_digest(signature):
        raise _pac_fork_proof_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("proof payload must be an object")
    if set(payload.keys()) != _PAC_FORK_PROOF_PAYLOAD_KEYS:
        raise _pac_fork_proof_invalid(
            "payload must contain exactly the keys 'chains', 'issuer', "
            "'keyVersion', 'moment', 'policy', 'report' and 'version'"
        )
    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _pac_fork_proof_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _pac_fork_proof_invalid("payload keyVersion must be positive")
    moment = payload[CP_MOMENT]
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("payload moment must be an int")
    if moment < 0:
        raise _pac_fork_proof_invalid("payload moment must be non-negative")
    policy_digest = payload[RECEIPT_POLICY]
    if not isinstance(policy_digest, str):
        raise TypeError("payload policy must be a str")
    if not _prune_is_digest(policy_digest):
        raise _pac_fork_proof_invalid(
            "payload policy must be 64 lowercase hex characters"
        )
    version = payload[VERSION]
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("payload version must be an int")
    if version != PRUNE_AGGREGATE_FORK_PROOF_VERSION:
        raise _pac_fork_proof_invalid("payload version must be the integer 1")
    chains = _validated_pac_fork_chains(payload[FORK_PROOF_CHAINS])
    _validated_pac_fork_report(payload[FORK_PROOF_REPORT], chains)

    if _prune_compact(data) != raw:
        raise _pac_fork_proof_invalid(
            "encoding is not the canonical compact form"
        )
    return payload, signature, chains


def sign_prune_aggregate_fork_proof(
    items, prune_policy, keyring, moment, issuer, version
):
    """Sign the fork summary of a prune aggregate chain batch.

    ``items`` is the same non-empty list of ``{"id", "root",
    "successors", "policies"}`` dicts
    :func:`verify_prune_aggregate_chains` takes; ``prune_policy`` is
    the shared invariant original pruning policy, ``keyring`` follows
    the existing rules, ``moment`` is the signing time and
    ``issuer``/``version`` name the signing credentials.  The batch
    first runs through the exact :func:`verify_prune_aggregate_chains`
    rules and the proof is issued only when the resulting report
    records at least one fork.  No file is read or written and no
    argument is modified.

    The proof is one canonical compact UTF-8 JSON object -- every
    object key recursively sorted, non-ASCII preserved, no trailing
    newline or any other trailing byte -- carrying exactly ``payload``
    and ``signature``.  The payload binds exactly ``chains``,
    ``issuer``, ``keyVersion``, ``moment``, ``policy`` (the lowercase
    hex SHA-256 of the canonical compact prune policy encoding),
    ``report`` (the complete chain-batch report) and ``version`` (the
    integer 1).  ``chains`` summarizes every input chain, strictly in
    input order with no reordering, omission or replacement: each entry
    carries exactly ``id``, ``root`` (the SHA-256 of the chain's root
    bytes), ``successors`` (the SHA-256 of each successor's complete
    bytes in chain order) and ``policies`` (the SHA-256 of each stage
    policy's canonical bytes in history order).  ``signature`` is the
    lowercase hex HMAC-SHA256 of the canonical compact payload bytes
    under the key the keyring binds to the exact issuer and version,
    with no fallback.

    A parameter or public field type fault raises :class:`TypeError`
    (a :class:`bool` never poses as an int); an empty list, an empty or
    duplicate id, a wrong policy count, an empty issuer, a non-positive
    version, a negative moment, an illegal shared policy value or a
    report without a fork raises :class:`ValueError`; and unknown,
    revoked, not-yet-valid or expired credentials raise
    :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_chain_batch(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_keyring = _validated_keyring(keyring)
    sign_moment = _fe_moment(moment, "moment")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    report = verify_prune_aggregate_chains(
        validated_items, prune_policy, keyring, sign_moment
    )
    if not report[CHAINS_FORKS]:
        raise ValueError(
            "a prune aggregate fork proof requires at least one fork in "
            "the chain report"
        )
    entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, sign_moment
    )
    payload = {
        FORK_PROOF_CHAINS: _pac_chain_materials(validated_items),
        VD_ISSUER: issuer,
        KEY_VERSION: version,
        CP_MOMENT: sign_moment,
        RECEIPT_POLICY: hashlib.sha256(
            _verdict_policy_bytes(validated_prune_policy)
        ).hexdigest(),
        FORK_PROOF_REPORT: copy.deepcopy(report),
        VERSION: PRUNE_AGGREGATE_FORK_PROOF_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _verify_pac_fork_proof_core(
    raw: bytes,
    validated_prune_policy: dict,
    validated_keyring: dict[str, list[dict]],
    verify_moment: int,
) -> dict:
    """Verify one fork proof against already-validated shared materials.

    This is the shared core of :func:`verify_prune_aggregate_fork_proof`
    and the batch :func:`verify_prune_aggregate_fork_proofs`; the caller
    owns the argument-type and shared-material validation.  The returned
    dict is freshly built solely from authenticated proof material.
    """
    payload, signature, chains = _parse_pac_fork_proof(raw)
    recomputed_policy = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()
    if payload[RECEIPT_POLICY] != recomputed_policy:
        raise _pac_fork_proof_invalid(
            "policy digest does not match the policy"
        )
    if payload[CP_MOMENT] > verify_moment:
        raise _pac_fork_proof_invalid(
            "moment must not be later than the verification moment"
        )

    entry = _usable_checkpoint_key(
        validated_keyring, payload[VD_ISSUER], payload[KEY_VERSION],
        verify_moment,
    )
    expected_signature = hmac.new(
        bytes.fromhex(entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,

        f"invalid prune aggregate fork decision: {message}"
    )


def _reject_duplicate_pafd_keys(pairs: list[tuple]) -> dict:
    """``object_pairs_hook`` turning duplicate decision keys into an error."""
    result: dict = {}
    for key, value in pairs:
        if key in result:
            raise _pafd_invalid(f"duplicate key {key!r} in object")
        result[key] = value
    return result


def _pac_fork_edge_object(entry: dict) -> dict:
    """One canonical ``{rootDigest, predecessorDigest, successors}`` edge."""
    return {
        PAC_ROOT_DIGEST: entry[PAC_ROOT_DIGEST],
        PAC_PREDECESSOR_DIGEST: entry[PAC_PREDECESSOR_DIGEST],
        PAC_BATCH_SUCCESSORS: list(entry[PAC_BATCH_SUCCESSORS]),
    }


def _pac_fork_proof_edges(payload: dict) -> list[dict]:
    """The complete fork edge set a verified fork proof binds.

    The proof parser already validated every fork entry, its ordering
    and its successor set, so the entries are copied verbatim in the
    report's own canonical (root, predecessor, successor) order.
    """
    return [
        _pac_fork_edge_object(fork)
        for fork in payload[FORK_PROOF_REPORT][CHAINS_FORKS]
    ]


def _pac_fork_edge_triples(
    edges: list[dict],
) -> tuple[tuple[str, str, tuple[str, ...]], ...]:
    """Order-preserving edge objects to comparable triples."""
    return tuple(
        (
            edge[PAC_ROOT_DIGEST],
            edge[PAC_PREDECESSOR_DIGEST],
            tuple(edge[PAC_BATCH_SUCCESSORS]),
        )
        for edge in edges
    )


def _sorted_pac_fork_edge_objects(
    triples: set | frozenset,
) -> list[dict]:
    """Unique fork edges sorted by (rootDigest, predecessorDigest, ...)."""
    return [
        {
            PAC_ROOT_DIGEST: root_digest,
            PAC_PREDECESSOR_DIGEST: predecessor,
            PAC_BATCH_SUCCESSORS: list(successors),
        }
        for root_digest, predecessor, successors in sorted(triples)
    ]


def _validated_pafd_edge(value: object, where: str) -> dict:
    """Validate one bound fork edge object into a fresh ordered dict."""
    if not isinstance(value, dict):
        raise TypeError(f"{where} edge must be an object")
    if set(value.keys()) != _PAFD_EDGE_KEYS:
        raise _pafd_invalid(
            f"{where} edge must contain exactly the keys 'predecessorDigest', "
            "'rootDigest' and 'successors'"
        )
    root_digest = value[PAC_ROOT_DIGEST]
    predecessor = value[PAC_PREDECESSOR_DIGEST]
    successors = value[PAC_BATCH_SUCCESSORS]
    if not isinstance(root_digest, str):
        raise TypeError(f"{where} edge rootDigest must be a str")
    if not isinstance(predecessor, str):
        raise TypeError(f"{where} edge predecessorDigest must be a str")
    if not _prune_is_digest(root_digest):
        raise _pafd_invalid(
            f"{where} edge rootDigest must be 64 lowercase hex characters"
        )
    if not _prune_is_digest(predecessor):
        raise _pafd_invalid(
            f"{where} edge predecessorDigest must be 64 lowercase hex "
            "characters"
        )
    if not isinstance(successors, list):
        raise TypeError(f"{where} edge successors must be a list")
    if not successors:
        raise _pafd_invalid(f"{where} edge successors must be non-empty")
    for position, successor in enumerate(successors):
        if not isinstance(successor, str):
            raise TypeError(
                f"{where} edge successor {position} must be a str"
            )
        if not _prune_is_digest(successor):
            raise _pafd_invalid(
                f"{where} edge successor {position} must be 64 lowercase "
                "hex characters"
            )
    if successors != sorted(successors) or len(set(successors)) != len(
        successors
    ):
        raise _pafd_invalid(
            f"{where} edge successors must be unique and sorted ascending"
        )
    return {
        PAC_ROOT_DIGEST: root_digest,
        PAC_PREDECESSOR_DIGEST: predecessor,
        PAC_BATCH_SUCCESSORS: list(successors),
    }


def _pafd_row(
    item_id: str,
    proof_digest: str,
    site: str | None,
    key_version: int | None,
    edges: list[dict] | None,
    conclusion: str,
    reason: str | None,
) -> dict:
    """One per-proof decision row with the fixed bound key set."""
    return {
        ADJ_CONCLUSION: conclusion,
        PAFD_EDGES: edges,
        ID: item_id,
        KEY_VERSION: key_version,
        PAFD_FORK_PROOF_DIGEST: proof_digest,
        ADJ_REASON: reason,
        VD_ISSUER: site,
    }


def _adjudicate_pac_fork_one(
    item: dict,
    prune_policy_digest: str,
    site_policy: dict,
    keyring: dict[str, list[dict]],
    moment: int,
) -> dict:
    """Verify, authorize and authenticate one fork proof in isolation.

    The proof is first checked through the exact
    :func:`verify_prune_aggregate_fork_proof` structural rules, then the
    signing site and key version are authorized exactly against the site
    policy with no fallback, and finally the HMAC is checked against the
    current keyring.  Any failure rejects just this row with one fixed
    reason and never affects the other items.
    """
    item_id = item[ID]
    raw_proof = item[FORK_PROOF_ITEM_PROOF]
    proof_digest = hashlib.sha256(raw_proof).hexdigest()

    def structural_invalid() -> dict:
        return _pafd_row(
            item_id, proof_digest, None, None, None,
            _PAFD_CONCLUSION_INVALID, _PAFD_REASON_INVALID_PROOF,
        )

    try:
        payload, signature, _chains = _parse_pac_fork_proof(raw_proof)
    except (TypeError, ValueError):
        return structural_invalid()

    site = payload[VD_ISSUER]
    key_version = payload[KEY_VERSION]
    try:
        edges = _pac_fork_proof_edges(payload)
    except (TypeError, ValueError):
        return structural_invalid()

    def reject(reason: str) -> dict:
        return _pafd_row(
            item_id, proof_digest, site, key_version, edges,
            _PAFD_CONCLUSION_INVALID, reason,
        )

    # The proof must be bound to the exact shared prune policy and must
    # not be dated after the adjudication moment; a mismatch makes the
    # claimed identity untrustworthy, so the row carries none.
    if payload[RECEIPT_POLICY] != prune_policy_digest:
        return structural_invalid()
    if payload[CP_MOMENT] > moment:
        return structural_invalid()

    allowed_versions = site_policy[ADJ_SITES].get(site)
    if allowed_versions is None:
        return reject(REASON_UNAUTHORIZED_SITE)
    if key_version not in allowed_versions:
        return reject(REASON_UNAUTHORIZED_VERSION)

    key_entry = None
    for candidate in keyring.get(site, ()):
        if candidate[VERSION] == key_version:
            key_entry = candidate
            break
    if key_entry is None:
        return reject(REASON_CREDENTIAL_UNAVAILABLE)
    if key_entry[REVOKED]:
        return reject(REASON_REVOKED)
    if moment < key_entry[NOT_BEFORE]:
        return reject(REASON_NOT_YET_VALID)
    if moment > key_entry[NOT_AFTER]:
        return reject(REASON_EXPIRED)

    expected_signature = hmac.new(
        bytes.fromhex(key_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    if not hmac.compare_digest(expected_signature, signature):
        return reject(REASON_BAD_SIGNATURE)

    return _pafd_row(
        item_id, proof_digest, site, key_version, edges,
        _PAFD_CONCLUSION_VALID, None,
    )


_PAFD_EDGE_SET = frozenset[tuple[str, str, tuple[str, ...]]]


def _pafd_content(row: dict) -> _PAFD_EDGE_SET:
    """The complete fork edge set one authenticated row declares."""
    return frozenset(_pac_fork_edge_triples(row[PAFD_EDGES]))


def _tally_pac_fork_rows(
    rows: list[dict],
) -> tuple[bool, dict[str, _PAFD_EDGE_SET]]:
    """Group authenticated rows per site by their complete edge sets.

    Two rows from one site are the same declaration only when their
    complete fork edge set -- every ``(rootDigest, predecessorDigest,
    successors)`` triple -- agrees, regardless of the proof digest.
    The smallest-id row of one identical set is the vote and extras are
    ``duplicate``, while two distinct edge sets from one site are both a
    ``contradiction``.  Returns ``(contradicted, votes)`` where
    ``votes`` maps each non-contradicting site to its one edge set.
    """
    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] in (
            _PAFD_CONCLUSION_VALID,
            _PAFD_CONCLUSION_DUPLICATE,
            _PAFD_CONCLUSION_CONTRADICTION,
        ):
            by_site.setdefault(row[VD_ISSUER], {}).setdefault(
                _pafd_content(row), []
            ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            ordered_groups = sorted(
                groups.values(),
                key=lambda members: min(member[ID] for member in members),
            )
            for members in ordered_groups:
                members.sort(key=lambda row: row[ID])
                members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_CONTRADICTION
                members[0][ADJ_REASON] = REASON_CONTRADICTION
                for extra in members[1:]:
                    extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                    extra[ADJ_REASON] = REASON_DUPLICATE
        else:
            content, members = next(iter(groups.items()))
            members.sort(key=lambda row: row[ID])
            members[0][ADJ_CONCLUSION] = _PAFD_CONCLUSION_VALID
            members[0][ADJ_REASON] = None
            for extra in members[1:]:
                extra[ADJ_CONCLUSION] = _PAFD_CONCLUSION_DUPLICATE
                extra[ADJ_REASON] = REASON_DUPLICATE
            votes[site] = content
    return contradicted, votes


def adjudicate_prune_aggregate_forks(
    items, prune_policy, site_policy, keyring, moment, issuer, version
):
    """Adjudicate multi-site prune aggregate fork proofs offline.

    ``items`` is a non-empty list; each item contains exactly a unique
    non-empty ``id`` and ``proof`` bytes produced by
    :func:`sign_prune_aggregate_fork_proof`.  ``prune_policy`` is the
    shared invariant original ``{"batch","sites","threshold"}`` pruning
    policy the proofs were issued against; ``site_policy`` carries
    exactly ``sites`` (a non-empty map of each authorized non-empty site
    to its non-empty set of allowed positive key versions) and
    ``threshold`` (a positive integer no greater than the site count).
    ``keyring`` follows the existing rules, ``moment`` is the
    non-negative adjudication moment and ``issuer``/``version`` name the
    adjudicator credentials.  No file is read or written and no input is
    modified.

    Every proof is first verified through the existing prune aggregate
    fork proof rules, then authorized by the exact signing site and key
    version its payload names with no fallback, then authenticated
    against the current keyring.  An invalid, unauthenticated or
    unauthorized proof rejects just that item with one fixed reason
    (``invalid-proof``, ``unauthorized-site``, ``unauthorized-version``,
    ``credential-unavailable``, ``revoked``, ``not-yet-valid``,
    ``expired`` or ``bad-signature``) while the later items are still
    processed.  For one site the complete fork edge set counts once --
    extra proofs declaring an identical edge set are ``duplicate`` --
    while distinct valid edge sets from one site are a
    ``contradiction``.  Distinct sites must agree exactly on the
    complete fork edge set made of the root digest, the forking
    predecessor digest and the sorted legal successor digests; any
    contradiction or cross-site disagreement is ``conflicted`` with a
    null common edge set and no majority can outvote it.  A unique edge
    set backed by at least the threshold of distinct sites is
    ``accepted``; the same unique set short of the threshold stays
    ``insufficient`` but keeps that common set; with no valid vote the
    common set is null.

    The result is one canonical compact UTF-8 JSON object with
    recursively sorted keys, non-ASCII preserved and no trailing byte,
    carrying exactly ``payload`` and ``signature``.  The payload binds
    exactly ``common`` (the sorted common fork edge set, or null),
    ``issuer``, ``items`` (the rows stably sorted by site then id, each
    carrying ``conclusion``, its authenticated ``edges`` or null, ``id``,
    ``keyVersion``, ``proofDigest``, ``reason`` and ``site``),
    ``keyVersion``, ``prunePolicyDigest``, ``proofs`` (each proof digest
    in the original input order), ``sitePolicyDigest``, ``status`` and
    ``version`` (the integer 1).  ``signature`` is the lowercase hex
    HMAC-SHA256 of the canonical compact payload bytes under the exact
    issuer/version key.

    A parameter, container or public-field type fault raises
    :class:`TypeError` (a :class:`bool` never poses as an int); an empty
    list, an empty or duplicate id, or an illegal prune/site policy,
    threshold, moment, issuer or version raises :class:`ValueError`;
    unknown, revoked, not-yet-valid or expired adjudicator credentials
    raise :class:`AuthenticationError`.
    """
    validated_items = _validated_pac_fork_proof_items(items)
    validated_prune_policy = _validated_adjudication_policy(prune_policy)
    validated_site_policy = _validated_prune_batch_site_policy(site_policy)
    validated_keyring = _validated_keyring(keyring)
    if isinstance(moment, bool) or not isinstance(moment, int):
        raise TypeError("moment must be an int")
    if moment < 0:
        raise ValueError("moment must be non-negative")
    if not isinstance(issuer, str):
        raise TypeError("issuer must be a str")
    if issuer == "":
        raise ValueError("issuer must be non-empty")
    if isinstance(version, bool) or not isinstance(version, int):
        raise TypeError("version must be an int")
    if version <= 0:
        raise ValueError("version must be positive")

    prune_policy_digest = hashlib.sha256(
        _verdict_policy_bytes(validated_prune_policy)
    ).hexdigest()

    proof_digests = [
        hashlib.sha256(item[FORK_PROOF_ITEM_PROOF]).hexdigest()
        for item in validated_items
    ]
    rows = [
        _adjudicate_pac_fork_one(
            item, prune_policy_digest, validated_site_policy,
            validated_keyring, moment,
        )
        for item in validated_items
    ]

    contradicted, votes = _tally_pac_fork_rows(rows)

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _PAFD_STATUS_CONFLICTED
        common = None
    elif len(edge_sets) == 1:
        common = _sorted_pac_fork_edge_objects(next(iter(edge_sets)))
        if len(votes) >= validated_site_policy[ADJ_THRESHOLD]:
            status = _PAFD_STATUS_ACCEPTED
        else:
            status = _PAFD_STATUS_INSUFFICIENT
    else:
        status = _PAFD_STATUS_INSUFFICIENT
        common = None

    rows.sort(
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        )
    )

    signing_entry = _usable_checkpoint_key(
        validated_keyring, issuer, version, moment
    )
    payload = {
        PAFD_COMMON: common,
        VD_ISSUER: issuer,
        ITEMS: [copy.deepcopy(row) for row in rows],
        KEY_VERSION: version,
        PAFD_PRUNE_POLICY_DIGEST: prune_policy_digest,
        PAFD_PROOFS: proof_digests,
        PAFD_SITE_POLICY_DIGEST: hashlib.sha256(
            _prune_batch_site_policy_bytes(validated_site_policy)
        ).hexdigest(),
        STATUS: status,
        VERSION: PRUNE_AGGREGATE_FORK_DECISION_VERSION,
    }
    signature = hmac.new(
        bytes.fromhex(signing_entry[SECRET]),
        _prune_compact(payload),
        hashlib.sha256,
    ).hexdigest()
    return _prune_compact({TICKET_PAYLOAD: payload, SIGNATURE: signature})


def _parse_pafd(raw: object) -> tuple[dict, str]:
    """Validate decision bytes structurally into ``(payload, signature)``.

    A non-bytes argument or a field of the wrong type raises
    :class:`TypeError` (a :class:`bool` never poses as an int); every
    encoding, key-set, version, digest or value-format fault raises
    :class:`InvalidAggregateForkDecisionError`.  The policy, tally and
    credential bindings are checked by
    :func:`verify_prune_aggregate_fork_decision`.
    """
    if not isinstance(raw, bytes):
        raise TypeError("decision must be bytes")
    if not raw or raw[-1:] in (b"\n", b"\r", b" ", b"\t"):
        raise _pafd_invalid(
            "must end with the closing brace, no trailing byte"
        )
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _pafd_invalid("is not valid UTF-8") from exc
    try:
        data = json.loads(
            text, object_pairs_hook=_reject_duplicate_pafd_keys
        )
    except json.JSONDecodeError as exc:
        raise _pafd_invalid("is not valid JSON") from exc

    if not isinstance(data, dict):
        raise TypeError("decision must be a JSON object")
    if set(data.keys()) != _PAFD_DECISION_TOP_KEYS:
        raise _pafd_invalid(
            "must contain exactly the keys 'payload' and 'signature'"
        )
    signature = data[SIGNATURE]
    if not isinstance(signature, str):
        raise TypeError("decision signature must be a str")
    if not _prune_is_digest(signature):
        raise _pafd_invalid(
            "signature must be 64 lowercase hex characters"
        )
    payload = data[TICKET_PAYLOAD]
    if not isinstance(payload, dict):
        raise TypeError("decision payload must be an object")
    if set(payload.keys()) != _PAFD_PAYLOAD_KEYS:
        raise _pafd_invalid(
            "payload must contain exactly the keys 'common', 'issuer', "
            "'items', 'keyVersion', 'prunePolicyDigest', 'proofs', "
            "'sitePolicyDigest', 'status' and 'version'"
        )

    issuer = payload[VD_ISSUER]
    if not isinstance(issuer, str):
        raise TypeError("payload issuer must be a str")
    if issuer == "":
        raise _pafd_invalid("payload issuer must be a non-empty str")
    key_version = payload[KEY_VERSION]
    if isinstance(key_version, bool) or not isinstance(key_version, int):
        raise TypeError("payload keyVersion must be an int")
    if key_version <= 0:
        raise _pafd_invalid("payload keyVersion must be positive")
    status = payload[STATUS]
    if not isinstance(status, str):
        raise TypeError("payload status must be a str")
    if status not in _PAFD_STATUSES:
        raise _pafd_invalid("payload status is not a known status")
    for field in (PAFD_PRUNE_POLICY_DIGEST, PAFD_SITE_POLICY_DIGEST):
        digest = payload[field]
        if not isinstance(digest, str):
            raise TypeError(f"payload {field} must be a str")
        if not _prune_is_digest(digest):
            raise _pafd_invalid(
                f"payload {field} must be 64 lowercase hex characters"
            )

    proofs = payload[PAFD_PROOFS]
    if not isinstance(proofs, list):
        raise TypeError("payload proofs must be a list")
    if not proofs:
        raise _pafd_invalid("payload proofs must be non-empty")
    for position, digest in enumerate(proofs):
        if not isinstance(digest, str):
            raise TypeError(f"payload proof {position} digest must be a str")
        if not _prune_is_digest(digest):
            raise _pafd_invalid(
                f"payload proof {position} digest must be 64 lowercase hex "
                "characters"
            )

    raw_rows = payload[ITEMS]
    if not isinstance(raw_rows, list):
        raise TypeError("payload items must be a list")
    if not raw_rows:
        raise _pafd_invalid("payload items must be non-empty")
    parsed_rows: list[dict] = []
    seen_ids: set[str] = set()
    for position, row in enumerate(raw_rows):
        where = f"payload item {position}"
        if not isinstance(row, dict):
            raise TypeError(f"{where} must be an object")
        if set(row.keys()) != _PAFD_ROW_KEYS:
            raise _pafd_invalid(
                f"{where} must contain exactly the keys 'conclusion', "
                "'edges', 'id', 'keyVersion', 'proofDigest', 'reason' and "
                "'site'"
            )
        row_id = row[ID]
        if not isinstance(row_id, str):
            raise TypeError(f"{where} id must be a str")
        if row_id == "":
            raise _pafd_invalid(f"{where} id must be non-empty")
        if row_id in seen_ids:
            raise _pafd_invalid(f"{where} repeats an id")
        seen_ids.add(row_id)
        digest = row[PAFD_FORK_PROOF_DIGEST]
        if not isinstance(digest, str):
            raise TypeError(f"{where} proofDigest must be a str")
        if not _prune_is_digest(digest):
            raise _pafd_invalid(
                f"{where} proofDigest must be 64 lowercase hex characters"
            )
        site = row[VD_ISSUER]
        if site is not None:
            if not isinstance(site, str):
                raise TypeError(f"{where} site must be a str or null")
            if site == "":
                raise _pafd_invalid(f"{where} site must be non-empty")
        row_key_version = row[KEY_VERSION]
        if isinstance(row_key_version, bool) or not isinstance(
            row_key_version, int
        ):
            if row_key_version is not None:
                raise TypeError(f"{where} keyVersion must be an int or null")
        elif row_key_version <= 0:
            raise _pafd_invalid(f"{where} keyVersion must be positive")
        if (site is None) != (row_key_version is None):
            raise _pafd_invalid(
                f"{where} site and keyVersion must be null together"
            )
        conclusion = row[ADJ_CONCLUSION]
        if not isinstance(conclusion, str):
            raise TypeError(f"{where} conclusion must be a str")
        if conclusion not in _PAFD_CONCLUSIONS:
            raise _pafd_invalid(f"{where} conclusion is not known")
        reason = row[ADJ_REASON]
        if conclusion == _PAFD_CONCLUSION_VALID:
            if reason is not None:
                raise _pafd_invalid(
                    f"{where} reason must be null for a valid item"
                )
        else:
            if not isinstance(reason, str):
                raise TypeError(f"{where} reason must be a str")
            if reason not in _PAFD_REASONS:
                raise _pafd_invalid(f"{where} reason is not known")
        if conclusion == _PAFD_CONCLUSION_INVALID:
            if reason not in _PAFD_INVALID_REASONS:
                raise _pafd_invalid(
                    f"{where} reason does not match an invalid item"
                )
        elif conclusion != _PAFD_CONCLUSION_VALID:
            if reason != conclusion:
                raise _pafd_invalid(
                    f"{where} reason must match its conclusion"
                )

        raw_edges = row[PAFD_EDGES]
        if raw_edges is not None:
            if not isinstance(raw_edges, list):
                raise TypeError(f"{where} edges must be a list or null")
            if not raw_edges:
                raise _pafd_invalid(
                    f"{where} edges must be non-empty for an authenticated "
                    "proof"
                )
            row_edges = [
                _validated_pafd_edge(value, where) for value in raw_edges
            ]
            triples = _pac_fork_edge_triples(row_edges)
            if len(set(triples)) != len(triples):
                raise _pafd_invalid(f"{where} edges must be unique")
            if list(triples) != sorted(triples):
                raise _pafd_invalid(f"{where} edges must be sorted ascending")
        identity_expected = reason != _PAFD_REASON_INVALID_PROOF
        if identity_expected:
            if site is None or raw_edges is None:
                raise _pafd_invalid(
                    f"{where} an authenticated proof must carry its site and "
                    "fork edges"
                )
        else:
            if site is not None or raw_edges is not None:
                raise _pafd_invalid(
                    f"{where} an invalid-proof item must carry no site or "
                    "fork edges"
                )
        parsed_rows.append(
            {
                ADJ_CONCLUSION: conclusion,
                PAFD_EDGES: (
                    None if raw_edges is None else [dict(edge)
                                                    for edge in row_edges]
                ),
                ID: row_id,
                KEY_VERSION: row_key_version,
                PAFD_FORK_PROOF_DIGEST: digest,
                ADJ_REASON: reason,
                VD_ISSUER: site,
            }
        )

    common = payload[PAFD_COMMON]
    if common is not None:
        if not isinstance(common, list):
            raise TypeError("payload common must be a list or null")
        if not common:
            raise _pafd_invalid(
                "a bound common edge set must be non-empty"
            )
        common_edges = [
            _validated_pafd_edge(value, "payload common")
            for value in common
        ]
        common_triples = _pac_fork_edge_triples(common_edges)
        if len(set(common_triples)) != len(common_triples) or list(
            common_triples
        ) != sorted(common_triples):
            raise _pafd_invalid(
                "payload common edges must be unique and sorted ascending"
            )

    decision_version = payload[VERSION]
    if isinstance(decision_version, bool) or not isinstance(
        decision_version, int
    ):
        raise TypeError("payload version must be an int")
    if decision_version != PRUNE_AGGREGATE_FORK_DECISION_VERSION:
        raise _pafd_invalid("payload version must be the integer 1")

    if _prune_compact(data) != raw:
        raise _pafd_invalid("encoding is not the canonical compact form")
    return payload, signature


def _reconcile_pafd(payload: dict, threshold: int) -> str:
    """Re-derive every aggregate binding of a parsed fork decision.

    Re-tallies the per-proof rows the signature covers -- row ordering,
    proof digests, duplicate/contradiction conclusions, the cross-site
    complete-edge-set agreement, the threshold acceptance and the
    claimed common set -- without seeing any fork proof.  Any mismatch
    raises :class:`InvalidAggregateForkDecisionError`; otherwise the
    derived status is returned.
    """
    rows = payload[ITEMS]
    proofs = payload[PAFD_PROOFS]
    if len(rows) != len(proofs):
        raise _pafd_invalid(
            "the items must cover every proof and vice versa"
        )
    expected_order = sorted(
        rows,
        key=lambda row: (
            row[VD_ISSUER] is not None,
            row[VD_ISSUER] or "",
            row[ID],
        ),
    )
    if [row[ID] for row in expected_order] != [row[ID] for row in rows]:
        raise _pafd_invalid("items must be sorted by site then id")
    row_digests = [row[PAFD_FORK_PROOF_DIGEST] for row in rows]
    if sorted(row_digests) != sorted(proofs):
        raise _pafd_invalid(
            "the bound proof digests must equal the per-item digests"
        )

    by_site: dict[str, dict[_PAFD_EDGE_SET, list[dict]]] = {}
    for row in rows:
        if row[ADJ_CONCLUSION] == _PAFD_CONCLUSION_INVALID:
            continue
        by_site.setdefault(row[VD_ISSUER], {}).setdefault(
            _pafd_content(row), []
        ).append(row)

    contradicted = False
    votes: dict[str, _PAFD_EDGE_SET] = {}
    for site, groups in by_site.items():
        if len(groups) > 1:
            contradicted = True
            expected_conclusion = _PAFD_CONCLUSION_CONTRADICTION
            expected_reason = REASON_CONTRADICTION
        else:
            expected_conclusion = _PAFD_CONCLUSION_VALID
            expected_reason = None
            votes[site] = next(iter(groups.keys()))
        for members_raw in groups.values():
            members = sorted(members_raw, key=lambda row: row[ID])
            for index, row in enumerate(members):
                if index == 0:
                    if row[ADJ_CONCLUSION] != expected_conclusion:
                        raise _pafd_invalid(
                            f"item {row[ID]!r} has the wrong conclusion"
                        )
                    if row[ADJ_REASON] != expected_reason:
                        raise _pafd_invalid(
                            f"item {row[ID]!r} has the wrong reason"
                        )
                else:
                    if row[ADJ_CONCLUSION] != _PAFD_CONCLUSION_DUPLICATE:
                        raise _pafd_invalid(
                            f"item {row[ID]!r} must be a duplicate"
                        )
                    if row[ADJ_REASON] != REASON_DUPLICATE:
                        raise _pafd_invalid(
                            f"item {row[ID]!r} must carry the duplicate "
                            "reason"
                        )
            representative = members[0]
            for row in members[1:]:
                if _pac_fork_edge_triples(
                    row[PAFD_EDGES]
                ) != _pac_fork_edge_triples(representative[PAFD_EDGES]):
                    raise _pafd_invalid(
                        f"item {row[ID]!r} duplicates a proof with a "
                        "different fork edge set"
                    )

    edge_sets = set(votes.values())
    if contradicted or len(edge_sets) > 1:
        status = _PAFD_STATUS_CONFLICTED
        expected_common = None
    elif len(edge_sets) == 1 and len(votes) >= threshold:
        status = _PAFD_STATUS_ACCEPTED
        expected_common = _sorted_pac_fork_edge_objects(
            next(iter(edge_sets))
        )
    elif len(edge_sets) == 1:
        status = _PAFD_STATUS_INSUFFICIENT
        expected_common = _sorted_pac_fork_edge_objects(
            next(iter(edge_sets))
        )
    else:
        status = _PAFD_STATUS_INSUFFICIENT
        expected_common = None

    if payload[STATUS] != status:
        raise _pafd_invalid("the status does not match the tallied items")
    if payload[PAFD_COMMON] != expected_common:
        raise _pafd_invalid(
            "the bound common edge set does not match the tallied items"
        )
    return status


def verify_prune_aggregate_fork_decision(
    decision, prune_policy, site_policy, keyring, moment
):
    """Re-verify a signed prune aggregate fork decision entirely offline.

    Only the decision bytes, the expected shared ``prune_policy``, the
    expected ``site_policy``, the current ``keyring`` and the
    verification ``moment`` are consulted -- no file is read or written
    and no argument is modified.  Verification validates the canonical
    encoding and every key set, recomputes both policy digests, re-tallies
    the bound per-proof rows purely from the signed payload (the
    original-order proof digest bindings, the site/id row ordering, the
    same-site duplicate/contradiction markings, the cross-site complete
    fork-edge-set agreement, the threshold outcome and the claimed
    common set), and checks the HMAC-SHA256 against the key the *current*
    keyring binds to the payload's exact issuer and version, usable at
    the verification moment, so a later revocation or expiry rejects
    the decision with no fallback.

    On success a fresh mapping is returned with the fixed keys
    ``common``, ``decisionDigest`` (the SHA-256 of the decision bytes),
    ``issuer``, ``items``, ``keyVersion``, ``prunePolicyDigest``,
    ``proofs``, ``sitePolicyDigest``, ``status`` and ``version`` (the
    integer 1).  A non-bytes decision or a public field of the wrong

    return {
        FAC_ROOT_DIGEST: root_digest,
        FAC_HEAD_DIGEST: hashlib.sha256(head_packet).hexdigest(),
        FAC_HEIGHT: view[FAC_HEIGHT],
        FAC_POLICY_VERSION: head_policy_version,
        STATUS: head_status,
        FAC_COMMON_DIGEST: common_digest,
    }


def verify_fork_aggregate_chain(
    root, successors, prune_policy, site_policy, policies, keyring, moment
):
    """Verify one fork aggregate supersession chain hop by hop, offline.

    ``root`` is the chain's cross-site fork decision aggregate packet
    and ``successors`` the ordered successor packets (possibly empty
    for a height-zero chain).  ``prune_policy`` is the invariant
    original ``{"batch", "sites", "threshold"}`` pruning policy,
    ``site_policy`` the invariant fork-proof site policy and
    ``policies`` the complete versioned decision site policy history --
    one entry per stage (the root policy plus one per successor), so
    its length is ``len(successors) + 1`` and the first carries
    ``policyVersion`` 1.  Only the root, the ordered successors, the two
    invariant policies, the policy history, the current keyring and the
    verification moment are consulted; no file is read or written and
    no input is modified.

    An empty successor list still verifies the root in full.  For a
    non-empty chain every hop is re-checked: the root, predecessor and
    height links, the append-only decision prefix, the old/new policy
    digests and single-step version rule, the non-decreasing effective
    moment, the invariant prune and fork-proof site policies, the
    per-new-decision re-authentication and the full stage re-tally, the
    verdict state machine and dual-policy sealer authorization, and the
    exact-issuer/version HMAC with a credential usable at both the
    hop's effective moment and the verification moment.

    On success returns a fresh mapping with the fixed keys
    ``rootDigest``, ``headDigest``, ``height`` (0 for a bare root),
    ``policyVersion`` (the head policy's version), ``status`` and
    ``commonDigest`` (the SHA-256 of the canonical common declaration
    when one is bound, otherwise null); repeated calls return equal but
    mutually independent results.  A non-bytes argument or a public
    field of the wrong type raises :class:`TypeError`; an empty value,
    an illegal version, a wrong policy count or a backwards moment
    raises :class:`ValueError`; a bad root raises
